func quotaSelected(c ProfileConfig, f QuotaUsageFilter, account string, at int64) bool {
	if f.Profile == "" {
		return true
	}
	assigned := false
	for _, p := range c.Profiles {
		if !quotaProfileContains(c, p, account, at) {
			continue
		}
		assigned = true
		if p.ID == f.Profile || f.Profile == "all" && !p.Archived {
			return true
		}
	}
	return f.Profile == "unassigned" && !assigned
}

func quotaWindowSelected(c ProfileConfig, f QuotaUsageFilter, w Window) bool {
	if f.Profile == "" {
		return true
	}
	for _, p := range c.Profiles {
		if p.ID != f.Profile && !(f.Profile == "all" && !p.Archived) {
			continue
		}
		if p.Memberships != nil {
			for _, m := range p.Memberships {
				if m.Account == w.Account && intervalsOverlap(Binding{Start: m.Start, End: m.End}, Binding{Start: w.Start, End: w.AttributionEnd}) {
					return true
				}
			}
		} else if p.Selection {
			if quotaProfileContains(c, p, w.Account, w.Start) {
				return true
			}
		} else {
			for _, b := range c.Bindings {
				if b.Profile == p.ID && b.Account == w.Account && intervalsOverlap(b, Binding{Start: w.Start, End: w.AttributionEnd}) {
					return true
				}
			}
		}
	}
	return f.Profile == "unassigned" && quotaSelected(c, f, w.Account, w.Start)
}

// QuotaUsage reads the retained ledger and observed windows directly. It does
// not execute the legacy exhaustion estimator or mutate historical accounting.
func (s *Service) QuotaUsage(ctx context.Context, f QuotaUsageFilter) (QuotaUsageReport, error) {
	r := QuotaUsageReport{Version: "quota-usage-v1", Profiles: []QuotaUsageProfile{}, Credentials: []ProfileCredential{}, Windows: []QuotaUsageWindow{}, Tiers: subscriptionTiers()}
	if !s.ready.Load() {
		return r, errors.New("usage history is initializing")
	}
	if f.Kind != "" && f.Kind != "5h" && f.Kind != "weekly" {
		return r, errors.New("unsupported window kind")
	}
	if f.Period == "" {
		f.Period = "current"
	}
	if f.Period != "current" && f.Period != "history" {
		return r, errors.New("invalid period")
	}
	if f.Basis == "" {
		f.Basis = "today"
	}
	if f.Basis != "today" && f.Basis != "then" {
		return r, errors.New("invalid comparison basis")
	}
	if !validCapacityRatio(f.CapacityRatio) {
		return r, errors.New("invalid capacity ratio")
	}
	if f.CapacityRatio > 0 {
		if _, ok := subscriptionTier(f.TargetPlan); !ok || f.WindowID == "" {
			return r, errors.New("a scenario needs a target tier and one selected window")
		}
	}
	if f.SourcePlan != "" {
		if _, ok := subscriptionTier(f.SourcePlan); !ok || f.WindowID == "" {
			return r, errors.New("source tier requires a selected window")
		}
	}
	if err := s.acquireHistory(ctx); err != nil {
		return r, err
	}
	defer s.releaseHistory()
	initialRevision := f.At > 0 && f.Revision == 0
	var err error
	f.ProfileFilter, err = s.pinProfileFilter(ctx, f.ProfileFilter)
	if err != nil {
		return r, err
	}
	revision := f.Revision
	if initialRevision {
		revision = -1
	}
	r.Config, err = s.ProfileConfig(ctx, revision)
	if err != nil {
		return r, err
	}
	f.Revision = r.Config.Revision
	found := f.Profile == "" || f.Profile == "all" || f.Profile == "unassigned"
	for _, p := range r.Config.Profiles {
		r.Profiles = append(r.Profiles, QuotaUsageProfile{Profile: p, Members: quotaProfileAccounts(r.Config, p)})
		if p.ID == f.Profile {
			found = true
		}
	}
	if !found {
		return r, errors.New("profile not found")
	}
	r.APIKeys, err = s.apiKeys(ctx, f.Through)
	if err != nil {
		return r, err
	}
	accounts, err := s.Accounts(ctx)
	if err != nil {
		return r, err
	}
	seen := map[string]bool{}
	windowFound := f.WindowID == ""
	for _, a := range accounts {
		if err := ctx.Err(); err != nil {
			return r, err
		}
		events, observations, err := s.evidence(ctx, a.ID, f.Through, f.ObservationsThrough)
		if err != nil {
			return r, err
		}
		cred := ProfileCredential{Account: a, Status: "unknown", Requests: int64(len(events))}
		_ = s.db.QueryRowContext(ctx, `SELECT checked_ms,status FROM analytics_credential_inventory WHERE account=?`, a.ID).Scan(&cred.Checked, &cred.Status)
		if cred.Checked == 0 || f.At-cred.Checked > max(int64(s.PollInterval/time.Millisecond)*2, 900000) {
			cred.Status = "unknown"
		}
		if len(events) > 0 {
			cred.First, cred.Last = events[0].Started, events[len(events)-1].Started
		}
		r.Credentials = append(r.Credentials, cred)
		if f.Account != "" && f.Account != a.ID {
			continue
		}
		windows := Derive(a, observations, events, f.At)
		latest := map[string]string{}
		if f.Period == "current" {
			observed := map[string]int64{}
			for _, w := range windows {
				key := w.Kind + "|" + w.Scope
				if w.Status == "current" && (latest[key] == "" || w.LastObserved > observed[key] || w.LastObserved == observed[key] && w.ID < latest[key]) {
					latest[key], observed[key] = w.ID, w.LastObserved
				}
			}
		}
		for _, w := range windows {
			if (w.Kind != "5h" && w.Kind != "weekly") || f.Kind != "" && f.Kind != w.Kind || !quotaWindowSelected(r.Config, f, w) {
				continue
			}
			if f.Period == "current" && latest[w.Kind+"|"+w.Scope] != w.ID {
				continue
			}

			if f.From > 0 && w.Reset <= f.From || f.To > 0 && w.Start >= f.To {
				continue
			}
			selected := ProfileTotals{}
			windowEvents := []Event{}
			for _, e := range events {
				if !inWindow(e, w) {
					continue
				}
				windowEvents = append(windowEvents, e)
				if !quotaSelected(r.Config, f, a.ID, e.Started) || !keyMatches(e, f.APIKey) || f.Model != "" && f.Model != e.Model {
					continue
				}
				selected.add(e)
				if !seen[e.Hash] {
					seen[e.Hash] = true
					r.MatchedTotals.add(e)
				}
			}
			if f.WindowID == w.ID {
				r.Totals = selected
			}
			qw := QuotaUsageWindow{ID: w.ID, Account: w.Account, Provider: w.Provider, Label: w.Label, Kind: w.Kind, Scope: w.Scope, Start: w.Start, Reset: w.Reset, LastObserved: w.LastObserved, Used: w.Final, Status: w.Status, Stale: f.At-w.LastObserved > 600000 && w.Status == "current", Assigned: !strings.HasPrefix(w.Scope, "unknown"), Selected: selected, AccountUsage: ProfileTotals{Tokens: w.Tokens, Requests: w.Requests, Failed: w.Failed, Unpriced: w.Unpriced, CostNano: w.CostNano}, Notes: w.Notes}
			qw.AttributionEnd = w.AttributionEnd

			qw.Notes = []string{"Requests are assigned by start time in [window start, reset). API costs use prices captured with each event; older prices may have been captured at ingestion, not at execution. Last observed quota is not necessarily the final reset reading."}
			if w.BoundaryRevision {
				qw.Notes = append(qw.Notes, "The provider revised this reset boundary; the earlier interval is retained as evidence.")
			}
			if w.Coverage != "observed interval" {
				qw.Notes = append(qw.Notes, w.Coverage)
			}
			if w.Straddling > 0 || w.BoundaryUncertain > 0 {
				qw.Notes = append(qw.Notes, "Some request timing overlaps a reset boundary; provider-side token allocation is unknown.")
			}
			if w.Tokens.Total > 0 && qw.Assigned {
				v := float64(selected.Tokens.Total) * 100 / float64(w.Tokens.Total)
				qw.TokenShare = &v
			}
			qw.Attribution = attributeKeyQuota(w, observations, windowEvents, f.APIKey, f.GatewayOnly)

			if f.APIKey != "" && (f.Model != "" || !selectionCoversKey(r.Config, f, w, windowEvents)) {
				qw.Attribution = QuotaAttribution{Status: "unavailable", Reason: "This selection covers only part of the key's account/window usage."}
			}
			qw.SourcePlan, qw.PlanBasis = planForWindow(r.Config, w), "recorded assignment"
			if f.WindowID == w.ID {
				windowFound = true
				if f.SourcePlan != "" {
					p, _ := subscriptionTier(f.SourcePlan)
					if p.Provider != w.Provider {
						return r, errors.New("source tier does not match window provider")
					}
					qw.SourcePlan, qw.PlanBasis = f.SourcePlan, "selected scenario"
				}
			}
			used := w.Final
			if f.APIKey == "" && selected.Requests != w.Requests {
				used = nil
			}
			if f.APIKey != "" {
				used = nil
				if qw.Attribution.Status == "estimate" {
					used = qw.Attribution.Percent
				}
			}
			ratio, target := 0.0, ""
			if f.WindowID == w.ID {
				ratio, target = f.CapacityRatio, f.TargetPlan
			}
			qw.Comparisons = compareSubscription(w, qw.SourcePlan, used, f.Basis, target, ratio)
			r.Windows = append(r.Windows, qw)
		}
	}
	if !windowFound {
		return r, errors.New("selected window is outside the current filters; choose another window")
	}
	if f.WindowID == "" {
		r.Totals = r.MatchedTotals
	}
	sort.Slice(r.Windows, func(i, j int) bool {
		a, b := r.Windows[i], r.Windows[j]
		if a.Reset != b.Reset {
			return a.Reset > b.Reset
		}
		return a.ID < b.ID
	})
	r.Filter = f
	return r, nil
}

func selectionCoversKey(c ProfileConfig, f QuotaUsageFilter, w Window, events []Event) bool {
	for _, e := range events {
		if inWindow(e, w) && keyMatches(e, f.APIKey) && !quotaSelected(c, f, e.Account, e.Started) {
			return false
		}
	}
	return true
}

type QuotaUsageEvidence struct {
	Valuation *WindowValuation `json:"valuation,omitempty"`
	Proof
	PriceBook         ComparisonPriceBook  `json:"price_book"`
	Value             APIValue             `json:"api_value"`
	Normalization     ProfileNormalization `json:"normalization"`
	Models            []ProfileBucket      `json:"models"`
	MeterObservations []Observation        `json:"meter_observations"`
	Filter            QuotaUsageFilter     `json:"filter"`
}

func (s *Service) QuotaEvidence(ctx context.Context, f QuotaUsageFilter) (QuotaUsageEvidence, error) {
	out := QuotaUsageEvidence{}
	if err := s.acquireHistory(ctx); err != nil {
		return out, err
	}
	defer s.releaseHistory()
	initialRevision := f.At > 0 && f.Revision == 0
	var err error
	f.ProfileFilter, err = s.pinProfileFilter(ctx, f.ProfileFilter)
	if err != nil {
		return out, err
	}
	revision := f.Revision
	if initialRevision {
		revision = -1
	}
	c, err := s.ProfileConfig(ctx, revision)
	if err != nil {
		return out, err
	}
	f.Revision = c.Revision
	out.PriceBook, err = s.comparisonPriceBook(ctx, f.ValuationRule)
	if err != nil {
		return out, err
	}
	f.ValuationRule = out.PriceBook.ID
	p, err := s.proofForValue(ctx, f.WindowID, f.Through, f.ObservationsThrough, f.At, out.PriceBook)
	if err != nil {
		return out, err
	}
	windowSelected := quotaWindowSelected(c, f, p.Window)
	if f.Profile == "unassigned" {
		for _, e := range p.Events {
			if quotaSelected(c, f, e.Account, e.Started) {
				windowSelected = true
				break
			}
		}
	}
	if !windowSelected || f.Account != "" && f.Account != p.Window.Account || f.From > 0 && p.Window.Reset <= f.From || f.To > 0 && p.Window.Start >= f.To || f.Kind != "" && f.Kind != p.Window.Kind {
		return out, errors.New("window is outside the selected profile or period")
	}
	if err = s.enrichTokenEvidence(ctx, p.Events, out.PriceBook, f.TokenEvidenceThrough); err != nil {
		return out, err
	}
	decision := windowValuation(p.Window, out.PriceBook)
	if out.PriceBook.Policy == profileValuePolicy {
		out.Valuation = &decision
	}
	for i := range p.Events {
		v := valueWindowEvent(p.Events[i], out.PriceBook, decision)
		p.Events[i].Value = &v
	}
	meterEvents, meterObs, err := s.evidence(ctx, p.Window.Account, f.Through, f.ObservationsThrough)
	if err != nil {
		return out, err
	}
	if err = s.enrichTokenEvidence(ctx, meterEvents, out.PriceBook, f.TokenEvidenceThrough); err != nil {
		return out, err
	}
	out.MeterObservations = []Observation{}
	for _, o := range meterObs {
		if o.Kind == p.Window.Kind && o.Scope == p.Window.Scope && o.Observed >= p.Window.Start && o.Observed < p.Window.AttributionEnd {
			out.MeterObservations = append(out.MeterObservations, o)
		}
	}

	out.Normalization = normalizeProfileWindow(p.Window, out.MeterObservations, meterEvents, out.PriceBook, f.ProfileFilter, normalizationPeriods(c, f.Profile, p.Window.Account, p.Window, f.ProfileFilter))
	models := map[string]*ProfileTotals{}
	selected := []Event{}
	for _, e := range p.Events {
		if quotaSelected(c, f, e.Account, e.Started) && keyMatches(e, f.APIKey) && (f.Model == "" || f.Model == e.Model) {
			selected = append(selected, e)
			out.Value.add(*e.Value)
			addBucket(models, e.Model, e)
		}
	}
	out.Models = buckets(models)
	p.SharedEvents, p.SharedReconciled = p.Events, p.Reconciled
	p.Events = selected
	p.Window = profileContribution(p.Window, selected)

	p.Window.TokensPerPercent, p.Window.EstimatedLimit, p.Window.EstimatedRemaining, p.Window.Exhaustion = nil, nil, nil, nil
	p.Window.CalibrationDelta = nil
	p.Window.CalibrationTokens, p.Window.CalibrationStart, p.Window.CalibrationEnd = 0, 0, 0
	p.Window.Notes = []string{"Quota observations and captured prices are retained as evidence. Quota percentages are account-level readings; selected requests may be only a contribution to the account."}
	var totals ProfileTotals
	for _, e := range selected {
		totals.add(e)
	}
	p.Reconciled = totals.Requests == p.Window.Requests && totals.Tokens == p.Window.Tokens && totals.CostNano == p.Window.CostNano
	p.Policy = "Recorded requests use the whole provider window and saved credential dates. Normalized values use only the displayed pair of quota readings and one pinned price book. Each model/category is priced separately; reasoning is included in output once. Unknown Claude write TTL is bounded by 5m/1h rates. Selected and shared events overlap. Captured prices/costs remain separate audit evidence."
	if out.Valuation != nil {
		p.Policy += " Window valuation is contextual: assumed_5m applies only to the pinned historical cohort and unknown remainder. Source tokens, captured costs and global event values are not rewritten. See valuation and price_book.historical for cutoff, H and checkpoint."
	}
	out.Proof, out.Filter = p, f
	return out, nil
}
